import { createStore } from './store.js';
import { bookPage, homePage, newBookPage, notFoundPage } from './views.js';

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url ?? '/', 'http://localhost');
    const path = decodeURIComponent(url.pathname);

    if (req.method === 'GET' && path === '/') {
      return send(res, 200, homePage(store.list()));
    }

    if (req.method === 'GET' && path === '/books/new') {
      return send(res, 200, newBookPage());
    }

    if (req.method === 'POST' && path === '/books') {
      const body = await readBody(req);
      const values = {
        title: body.get('title') ?? '',
        author: body.get('author') ?? '',
        notes: body.get('notes') ?? '',
      };
      try {
        const book = store.add(values);
        return redirect(res, `/books/${encodeURIComponent(book.id)}`);
      } catch (error) {
        return send(res, 400, newBookPage({ error: error.message, values }));
      }
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const book = store.finish(finishMatch[1]);
      if (!book) return send(res, 404, notFoundPage());
      return redirect(res, `/books/${encodeURIComponent(book.id)}`);
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (req.method === 'GET' && bookMatch) {
      const book = store.get(bookMatch[1]);
      if (!book) return send(res, 404, notFoundPage());
      return send(res, 200, bookPage(book));
    }

    return send(res, 404, notFoundPage());
  };
}

export function startServer({ filePath, port = 3000, host = '127.0.0.1' } = {}) {
  const store = createStore(filePath);
  const server = createServer(createApp(store));
  return new Promise((resolve) => {
    server.listen(port, host, () => {
      const address = server.address();
      resolve({
        server,
        port: typeof address === 'object' && address ? address.port : port,
        url: `http://${host}:${typeof address === 'object' && address ? address.port : port}`,
      });
    });
  });
}

function send(res, status, html) {
  res.writeHead(status, { 'content-type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      resolve(new URLSearchParams(raw));
    });
    req.on('error', reject);
  });
}
"}

