const port = Number(process.env.PORT) || 3000;

const { url } = await startServer({ filePath, port });
console.log(`Books app listening at ${url}`);

import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { startServer } from './server.js';

const servers = [];

afterEach(async () => {
  while (servers.length) {
    const server = servers.pop();
    await new Promise((resolve) => server.close(resolve));
  }
});

describe('books app', () => {
  it('lists current and finished books, adds one, finishes it, and serves a shareable page', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'books-'));
    const started = await startServer({ filePath: join(dir, 'books.json'), port: 0 });
    servers.push(started.server);

    const home = await fetch(started.url);
    expect(home.status).toBe(200);
    const homeHtml = await home.text();
    expect(homeHtml).toContain('Currently reading');
    expect(homeHtml).toContain('Finished');
    expect(homeHtml).toContain('Nothing in progress yet.');

    const created = await fetch(`${started.url}/books`, {
      method: 'POST',
      headers: { 'content-type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        title: 'The Left Hand of Darkness',
        author: 'Ursula K. Le Guin',
        notes: 'Winter and dualities.',
      }),
      redirect: 'manual',
    });
    expect(created.status).toBe(303);
    const location = created.headers.get('location');
    expect(location).toMatch(/^\/books\/[^/]+$/);

    const page = await fetch(started.url + location);
    expect(page.status).toBe(200);
    const pageHtml = await page.text();
    expect(pageHtml).toContain('The Left Hand of Darkness');
    expect(pageHtml).toContain('Ursula K. Le Guin');
    expect(pageHtml).toContain('Winter and dualities.');

    const finished = await fetch(`${started.url}${location}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });
    expect(finished.status).toBe(303);

    const after = await fetch(started.url);
    const afterHtml = await after.text();
    expect(afterHtml).toContain('The Left Hand of Darkness');
    expect(afterHtml).toContain('Nothing in progress yet.');
    const finishedHeading = afterHtml.indexOf('Finished');
    expect(afterHtml.indexOf('The Left Hand of Darkness')).toBeGreaterThan(finishedHeading);
  });
});

